{
  "replacements": [
    {
      "paragraphId": "P4",
      "text": "执事没有立刻接木牌，先看了你一眼，又垂目去看刻痕。他的手指在牌面边缘停了一瞬，没有碰那粒金屑，也没有把纸片拿过去。"
    },
    {
      "paragraphId": "P5",
      "text": "他抬眼问：“你刮的时候，泥是干的还是湿的？”"
    },
    {
      "paragraphId": "P6",
      "text": "你答是干的。执事点点头，把木牌推回你面前，语气平平：“金屑我没见过，也说不好是什么。”"
    },
    {
      "paragraphId": "P7",
      "text": "他顿了顿，目光落在你脸上：“你留着那粒金屑，等试炼完了再问。”"
    }
  ]
}

